        ServerSentEvent(event="bad\rnewline")
        print("Failed: event carriage return not caught")
    except ValueError as e:
        print(f"Caught expected error for event carriage return: {e}")

    try:
        ServerSentEvent(id="bad\rnewline")
        print("Failed: id carriage return not caught")
    except ValueError as e:
        print(f"Caught expected error for id carriage return: {e}")

    try:
        ServerSentEvent(id="bad\0null")
        print("Failed: id null not caught")
    except ValueError as e:
        print(f"Caught expected error for id null: {e}")

    print("Testing valid ServerSentEvent...")
    try:
